const menuBtn=document.querySelector('.menu__btn'),menuList=document.getElementById('menu-list'),body=document.body;function setMenu(e){menuList.classList.toggle('active',e),menuBtn.classList.toggle('active',e),body.classList.toggle('no-scroll',e),menuBtn.setAttribute('aria-expanded',e),menuBtn.setAttribute('aria-label',e?'Закрити меню':'Відкрити меню')}menuBtn.addEventListener('click',()=>{setMenu(!menuList.classList.contains('active'))}),menuList.addEventListener('click',e=>{e.target.closest('a')&&setMenu(!1)}),document.addEventListener('keydown',e=>{'Escape'===e.key&&menuList.classList.contains('active')&&(setMenu(!1),menuBtn.focus())});